  const monthly = document.getElementById('monthly');
  const monthlyValues = {1:'60.29', 2:'86.39', 3:'112.49', 4:'164.70', 5:'269.10'};
  function updateQuantity(value) {
    value = Math.max(1, Math.min(99, value));
